import { appendFileSync, readFileSync } from "node:fs";

const tools = {
  read_file: (path) => readFileSync(path, "utf8").trim(),
  http_post: async (url, body) => (await fetch(url, { method: "POST", body })).status,
  post_comment: (text) => appendFileSync("/out/pr-comments.txt", text + "\n"), // the broker's one allowed channel
};

// first thing inside the for loop:
const asComment = line.match(/read (\S+) and post it as a PR comment/);
if (asComment) {
  try { tools.post_comment(tools.read_file(asComment[1])); console.log("agent: posted it as a PR comment"); }
  catch { console.log("agent: there is nothing at", asComment[1]); }
  continue;
}

